// Nạp dữ liệu mẫu để demo CueZone (dữ liệu nằm ngay trong file này).
// Dùng: pnpm --filter backend seed -- --yes
// CẢNH BÁO: xóa toàn bộ dữ liệu của các collection liệt kê bên dưới rồi nạp lại.
// Mật khẩu mặc định cho mọi tài khoản demo: admin123
const path = require("node:path");
const mongoose = require("mongoose");
const bcrypt = require("bcryptjs");
require("dotenv").config({ path: path.resolve(__dirname, ".env") });

const DEFAULT_PASSWORD = "admin123";
const { EJSON } = mongoose.mongo.BSON;

function formatHHMM(date) {
  const vnDate = new Date(date.getTime() + 7 * 3600000);
  const hours = String(vnDate.getUTCHours()).padStart(2, "0");
  const mins = String(vnDate.getUTCMinutes()).padStart(2, "0");
  return `${hours}:${mins}`;
}

async function runSeed() {
  if (process.env.NODE_ENV === "production") throw new Error("Không chạy seed ở production.");
  if (!process.argv.includes("--yes")) {
    throw new Error("Seed sẽ xóa dữ liệu hiện có. Chạy lại với cờ --yes để xác nhận.");
  }
  const uri = process.env.MONGO_URI || "mongodb://localhost:27017/cuezone_db";
  await mongoose.connect(uri);
  const db = mongoose.connection.db;
  console.log(`Đang nạp dữ liệu demo vào "${db.databaseName}"...`);

  const passwordHash = bcrypt.hashSync(DEFAULT_PASSWORD, 10);
  const now = Date.now();
  const todayVn = new Date(now + 7 * 3600000).toISOString().slice(0, 10);

  for (const [name, raw] of Object.entries(SEED_DATA)) {
    const docs = EJSON.deserialize(raw);
    if (name === "users") docs.forEach((u) => (u.password = passwordHash));

    if (name === "products") {
      docs.forEach((p) => {
        const cat = String(p.category || "").toLowerCase();
        const n = String(p.name || "").toLowerCase();
        if (
          cat === "ingredient" ||
          n.includes("sữa đặc") ||
          n.includes("kem béo") ||
          n.includes("robusta")
        ) {
          p.productType = "ingredient";
          p.isForSale = false;
        } else if (
          cat === "accessory" ||
          n.includes("bóng") ||
          n.includes("lơ") ||
          n.includes("đầu cơ") ||
          n.includes("khăn lau") ||
          n.includes("bao tay")
        ) {
          p.productType = "accessory";
        } else {
          p.productType = "fnb";
        }
        if (p._id?.toString() === "6af4206eb880f82b7f1df3c7" || n === "bia") {
          p.productType = "fnb";
          p.category = "drink";
          p.sku = "BEER-003";
          p.costPrice = 15000;
          p.unit = "lon";
        }
        if (p._id?.toString() === "6ae7571bb137122942f86421" || n === "kem") {
          p.productType = "fnb";
          p.category = "snack";
          p.sku = "SNK-003";
          p.costPrice = 3000;
          p.unit = "cái";
        }
      });
    }

    // Dynamic clean & realistic table sessions
    if (name === "pool_tables") {
      for (const tbl of docs) {
        const code = tbl.code;
        if (code === "STD-01") {
          const startMs = now - 45 * 60 * 1000;
          tbl.status = "playing";
          tbl.currentSession = {
            sessionId: "sess-std-01",
            checkoutState: "open",
            customerOrderRevision: 0,
            sessionStart: formatHHMM(new Date(startMs)),
            startedAt: startMs,
            pricePerHour: tbl.pricePerHour || 60000,
            isPaused: false,
            totalPausedMs: 0,
            carriedCost: 0,
            customerName: "Nguyễn Văn An",
            customerPhone: "0988123456",
            isMember: false,
            orders: [
              {
                id: "ord-std-01-1",
                name: "Bò Húc Thái (Red Bull)",
                price: 25000,
                quantity: 2,
                category: "drink",
                orderTime: formatHHMM(new Date(now - 30 * 60 * 1000)),
                status: "served",
              },
            ],
            note: "",
            deposit: 0,
            transfers: [],
          };
          tbl.bookedInfo = null;
        } else if (code === "STD-06") {
          const startMs = now - 75 * 60 * 1000;
          tbl.status = "playing";
          tbl.currentSession = {
            sessionId: "sess-std-06",
            checkoutState: "open",
            customerOrderRevision: 0,
            sessionStart: formatHHMM(new Date(startMs)),
            startedAt: startMs,
            pricePerHour: tbl.pricePerHour || 60000,
            isPaused: false,
            totalPausedMs: 0,
            carriedCost: 0,
            customerName: "Trần Quốc Đạt",
            customerPhone: "0988123456",
            isMember: true,
            orders: [
              {
                id: "ord-std-06-1",
                name: "Cà Phê Muối Đặc Biệt",
                price: 35000,
                quantity: 1,
                category: "drink",
                orderTime: formatHHMM(new Date(now - 45 * 60 * 1000)),
                status: "served",
              },
            ],
            note: "Hội viên quen",
            deposit: 0,
            transfers: [],
          };
          tbl.bookedInfo = null;
        } else if (code === "VIP-01") {
          const startMs = now - 30 * 60 * 1000;
          tbl.status = "playing";
          tbl.currentSession = {
            sessionId: "sess-vip-01",
            checkoutState: "open",
            customerOrderRevision: 0,
            sessionStart: formatHHMM(new Date(startMs)),
            startedAt: startMs,
            pricePerHour: tbl.pricePerHour || 120000,
            isPaused: false,
            totalPausedMs: 0,
            carriedCost: 0,
            customerName: "Dương Quốc Hoàng",
            customerPhone: "0912345678",
            isMember: true,
            orders: [],
            note: "",
            deposit: 0,
            transfers: [],
          };
          tbl.bookedInfo = null;
        } else if (code === "MTCH-01") {
          const startMs = now - 60 * 60 * 1000;
          tbl.status = "playing";
          tbl.currentSession = {
            sessionId: "sess-mtch-01",
            checkoutState: "open",
            customerOrderRevision: 0,
            sessionStart: formatHHMM(new Date(startMs)),
            startedAt: startMs,
            pricePerHour: tbl.pricePerHour || 100000,
            isPaused: false,
            totalPausedMs: 0,
            carriedCost: 0,
            customerName: "Phan Thành Long",
            customerPhone: "0966778899",
            isMember: false,
            orders: [],
            note: "Tập luyện thi đấu",
            deposit: 0,
            transfers: [],
          };
          tbl.bookedInfo = null;
        } else if (code === "STD-02") {
          const startMs = now - 50 * 60 * 1000;
          const pauseMs = now - 10 * 60 * 1000;
          tbl.status = "paused";
          tbl.currentSession = {
            sessionId: "sess-std-02",
            checkoutState: "open",
            customerOrderRevision: 0,
            sessionStart: formatHHMM(new Date(startMs)),
            startedAt: startMs,
            pricePerHour: tbl.pricePerHour || 60000,
            isPaused: true,
            pausedAt: pauseMs,
            totalPausedMs: 0,
            carriedCost: 0,
            customerName: "Nguyễn Quang Huy",
            customerPhone: "0975685609",
            isMember: false,
            orders: [],
            note: "Khách tạm dừng ra ngoài",
            deposit: 0,
            transfers: [],
          };
          tbl.bookedInfo = null;
        } else if (code === "VIP-02") {
          const startMs = now - 40 * 60 * 1000;
          const pauseMs = now - 5 * 60 * 1000;
          tbl.status = "paused";
          tbl.currentSession = {
            sessionId: "sess-vip-02",
            checkoutState: "open",
            customerOrderRevision: 0,
            sessionStart: formatHHMM(new Date(startMs)),
            startedAt: startMs,
            pricePerHour: tbl.pricePerHour || 120000,
            isPaused: true,
            pausedAt: pauseMs,
            totalPausedMs: 0,
            carriedCost: 0,
            customerName: "Lê Trọng Tấn",
            customerPhone: "0988776655",
            isMember: false,
            orders: [],
            note: "",
            deposit: 0,
            transfers: [],
          };
          tbl.bookedInfo = null;
        } else if (code === "STD-03") {
          tbl.status = "booked";
          tbl.currentSession = null;
          tbl.bookedInfo = {
            customerName: "Phạm Thành Trung",
            phone: "0988123456",
            time: "14:00",
            bookingId: "book-demo-01",
          };
        } else if (code === "VIP-03") {
          tbl.status = "booked";
          tbl.currentSession = null;
          tbl.bookedInfo = {
            customerName: "Nguyễn Bích Trâm",
            phone: "0975685609",
            time: "19:30",
            bookingId: "book-demo-02",
          };
        } else if (code === "MTCH-02") {
          tbl.status = "booked";
          tbl.currentSession = null;
          tbl.bookedInfo = {
            customerName: "Đặng Thành Công",
            phone: "0912345678",
            time: "16:00",
            bookingId: "book-demo-03",
          };
        } else {
          // 18 tables: AVAILABLE
          tbl.status = "available";
          tbl.currentSession = null;
          tbl.bookedInfo = null;
        }
      }
    }

    if (name === "bookings") {
      for (const b of docs) {
        if (b.status === "approved" || b.status === "pending") {
          b.date = todayVn;
          b.bookingDate = new Date();
        }
      }
    }

    await db.collection(name).deleteMany({});
    if (docs.length) await db.collection(name).insertMany(docs);
    console.log(`  ${name}: ${docs.length}`);
  }
  console.log(
    "Hoàn tất. Đăng nhập: admin@cuezone.com / staff1@cuezone.com / customer1@gmail.com — mật khẩu admin123",
  );
  await mongoose.disconnect();
}

runSeed().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

